<?php
require __DIR__.'/workflow_checks.php';
use Illuminate\Support\Facades\DB;
use App\Services\{AreaRouting,PickupRequests,Dispatch,CourierCapacity};
$before=$n;
DB::table('assignments')->where('rider_id',$rider)->whereIn('status',['offered','accepted'])->update(['status'=>'completed']);
DB::table('users')->where('id',$rider)->update(['online'=>1,'last_seen_at'=>now()]);
$ids=[];for($i=0;$i<19;$i++)$ids[]=DB::table('assignments')->insertGetId(['parcel_id'=>$pid,'rider_id'=>$rider,'kind'=>$i%2?'delivery':'pickup','status'=>'accepted','created_at'=>now(),'updated_at'=>now()]);
$order=DB::table('orders')->insertGetId(['buyer_id'=>$buyer,'seller_id'=>$seller,'address_id'=>$address,'address_snapshot'=>DB::table('orders')->find($oid)->address_snapshot,'status'=>'PREPARING','total'=>150,'shipping_fee'=>50,'merchandise_total'=>100,'created_at'=>now(),'updated_at'=>now()]);$parcel=DB::table('parcels')->insertGetId(['order_id'=>$order,'tracking_code'=>'TWENTY-CAPACITY-TEST','status'=>'PREPARING','center_id'=>$center,'created_at'=>now(),'updated_at'=>now()]);$pObj=DB::table('parcels')->find($parcel);
ok(AreaRouting::riders($pObj,'pickup')->contains('id',$rider),'Pickup rider eligible with 19 mixed jobs');ok(AreaRouting::riders($pObj,'delivery')->contains('id',$rider),'Delivery rider eligible with 19 mixed jobs');
$a=DB::table('assignments')->insertGetId(['parcel_id'=>$parcel,'rider_id'=>null,'kind'=>'pickup','status'=>'requested','expires_at'=>now()->addHours(12),'created_at'=>now(),'updated_at'=>now()]);loginAs($company);PickupRequests::offer($a,$company,$rider);ok(DB::table('assignments')->find($a)->status==='offered','Twentieth pickup can be offered');ok(!AreaRouting::riders($pObj,'pickup')->contains('id',$rider)&&!AreaRouting::riders($pObj,'delivery')->contains('id',$rider),'Twenty shared offered/accepted jobs hide rider from both selection lists');loginAs($rider);Dispatch::accept($a,$rider);ok(DB::table('assignments')->find($a)->status==='accepted','Twentieth assignment can be accepted');
$stale=DB::table('assignments')->insertGetId(['parcel_id'=>$parcel,'rider_id'=>$rider,'kind'=>'delivery','status'=>'offered','expires_at'=>now()->addHour(),'created_at'=>now()]);try{Dispatch::accept($stale,$rider);throw new RuntimeException('Twenty-first job accepted');}catch(Illuminate\Validation\ValidationException $e){ok(isset($e->errors()['assignment']),'Twenty-first stale offer cannot be accepted');}DB::table('assignments')->where('id',$stale)->update(['status'=>'declined']);DB::table('assignments')->where('id',$ids[0])->update(['status'=>'completed']);ok(AreaRouting::riders($pObj,'pickup')->contains('id',$rider)&&AreaRouting::riders($pObj,'delivery')->contains('id',$rider),'Completing a job frees capacity in both lists');ok(CourierCapacity::limit((object)['courier_type'=>'driver'])===3,'Driver limit remains three trips');echo 'PASS: '.($n-$before)." rider capacity checks.\n";
